  ('uang-kita', 4, 'Money We Don''t Talk About', 'The parts most couples keep quiet about.'),
  ('uang-kita', 5, 'For Richer or Poorer', 'The promises we keep when money gets hard.'),
  ('menuju-pelaminan', 4, 'Two Families, One Wedding', 'When both families have a say in the big day.'),
  ('menuju-pelaminan', 5, 'Long After the Wedding', 'What we promise each other once the guests go home.'),
  ('rumah-dan-anak', 4, 'The Tricky Parts', 'The practical stuff couples tend to skip.'),
  ('rumah-dan-anak', 5, 'Whatever Comes', 'The fears and hopes under all the plans.'),
  ('saat-kita-berbeda', 4, 'Behind the Fight', 'What we bring into an argument without noticing.'),
  ('saat-kita-berbeda', 5, 'The Way Back', 'What we fear in a fight, and how we make it right.'),
  ('bahasa-sayang', 4, 'Harder to Say', 'The things we usually keep to ourselves.'),
  ('bahasa-sayang', 5, 'Still Choosing You', 'Love on the hard days, and for the long run.'),
  ('mimpi-berdua', 4, 'What It Costs', 'The hard side of wanting something big.'),
  ('mimpi-berdua', 5, 'Whatever Comes', 'When plans fall apart, and what we leave behind.'),
  ('iman-dan-nilai', 4, 'Doubts & Differences', 'The parts we''re still unsure about, said out loud.'),
  ('iman-dan-nilai', 5, 'What We Stand For', 'Forgiveness, and what we hope our life will say.'),
  ('seru-aja', 4, 'Plot Twists', 'Sillier choices and a few small confessions.'),
  ('seru-aja', 5, 'Full Chaos Mode', 'Absurd what-ifs and wild guesses about each other.')
) as v(slug, level_number, title, description)
join public.deep_talk_packs p on p.slug = v.slug
on conflict (pack_id, level_number) do nothing;

